import { Component, input } from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';

/** hrm-text-cell — ô hai dòng: nội dung chính (đậm) + dòng phụ (mờ). Icon dẫn đầu tuỳ chọn.
 *  Dùng cho cột "chức danh + thâm niên", "mã + mô tả"… Icon = Tabler object. */
@Component({
  selector: 'hrm-text-cell',
  imports: [TablerIconComponent],
  template: `
    @if (icon()) {
      <span class="tc-ic"><tabler-icon [icon]="$any(icon())" [size]="18" /></span>
    }
    <span class="tc-body">
      <span class="tc-primary">{{ primary() }}</span>
      @if (secondary()) { <span class="tc-secondary">{{ secondary() }}</span> }
    </span>
  `,
  host: { class: 'hrm-text-cell', '[attr.data-align]': 'align()' },
  styles: [`
/* display:flex (block-level) — không tham gia baseline của td, gióng ngang với Ô người dùng trong cùng dòng. */
:host { display: flex; align-items: center; gap: 8px; min-width: 0; max-width: 100%; }
:host([data-align='right']) { justify-content: flex-end; text-align: right; }
.tc-ic { display: inline-flex; color: var(--icon-secondary); flex: none; }
.tc-body { display: flex; flex-direction: column; min-width: 0; }
.tc-primary { font-size: var(--fs-14); color: var(--text-strong); line-height: 1.35;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tc-secondary { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.3;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  `],
})
export class HrmTextCell {
  readonly primary = input('');
  readonly secondary = input('');
  /** Icon Tabler dẫn đầu (object mode). null = không icon. */
  readonly icon = input<unknown>(null);
  readonly align = input<'left' | 'right'>('left');
}
